/* @lc app=leetcode id=2642 lang=kotlin */ class Graph(val n: Int, edges: Array<IntArray>, val g: HashMap<Int, MutableList<IntArray>> = HashMap<Int, MutableList<IntArray>>().also { m -> edges.forEach { m.getOrPut(it[0]) { mutableListOf() }.add(it) } }) { fun addEdge(edge: IntArray) { g.getOrPut(edge[0]) { mutableListOf() }.add(edge) } fun shortestPath(node1: Int, node2: Int): Int = IntArray(n) { Int.MAX_VALUE }.also { it[node1] = 0 }.let { d -> java.util.PriorityQueue<IntArray>(compareBy<IntArray> { it[0] }).also { it.add(intArrayOf(0, node1)) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> g[u].orEmpty().filter { e -> c + e[2] < d[e[1]] }.forEach { e -> pq.add(intArrayOf(c + e[2], e[1])).also { d[e[1]] = c + e[2] } } }.let { d[node2].let { if (it == Int.MAX_VALUE) -1 else it } } } } }